/**
 * Track geometry sidecar — `public/data/activities.tracks.json`
 * ({ "<run_id>": "<encoded polyline>" }), generated by `run_page/gen_lite.mjs`.
 *
 * dashboard_pro loads summaries from `activities.lite.json` (no polylines) and
 * only fetches this file when a map / track wall actually needs geometry.
 * Missing file is not an error: callers fall back to "no track for this run".
 */

const BASE = (import.meta.env.BASE_URL || '/').replace(/\/?$/, '/');
const TRACKS_URL = `${BASE}data/activities.tracks.json`;

type TrackMap = Record<string, string>;

let tracksPromise: Promise<TrackMap | null> | null = null;
let tracksCache: TrackMap | null = null;

function loadTracks(): Promise<TrackMap | null> {
  tracksPromise ??= fetch(TRACKS_URL)
    .then((res) => {
      if (!res.ok) return null;
      const type = res.headers.get('content-type') ?? '';
      // Dev servers answer unknown paths with index.html.
      if (type.includes('text/html')) return null;
      return res.json() as Promise<TrackMap>;
    })
    .then((data) => {
      if (data && typeof data === 'object') {
        tracksCache = data;
        return data;
      }
      return null;
    })
    .catch(() => null);
  return tracksPromise;
}

/** Synchronous peek: null until the sidecar has been fetched. */
export function getLoadedTracks(): TrackMap | null {
  return tracksCache;
}

/** Polyline for one run, or null when absent / sidecar unavailable. */
export async function getTrackFor(runId: number): Promise<string | null> {
  const tracks = await loadTracks();
  return tracks?.[String(runId)] ?? null;
}

/** Kick off the fetch (safe to call repeatedly). */
export function preloadTracks(): Promise<TrackMap | null> {
  return loadTracks();
}

/**
 * Merge tracks into a lite activity list. Activities without geometry keep
 * `summary_polyline: null` so existing empty states still apply.
 */
export async function withTracks(
  activities: { run_id: number; summary_polyline: string | null }[]
): Promise<{ run_id: number; summary_polyline: string | null }[]> {
  const tracks = await loadTracks();
  if (!tracks) return activities;
  return activities.map((a) => {
    const polyline = tracks[String(a.run_id)];
    return polyline ? { ...a, summary_polyline: polyline } : a;
  });
}
